CREATE DATABASE IF NOT EXISTS askustours_test_legacy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE askustours;

CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE banners (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,subtitle VARCHAR(255),image_path VARCHAR(255),link_url VARCHAR(255),sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_en VARCHAR(100) NOT NULL,name_ar VARCHAR(100),icon VARCHAR(80),sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_en VARCHAR(120) NOT NULL,name_ar VARCHAR(120),short_description TEXT,image_path VARCHAR(255),price_from DECIMAL(10,2) DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE destinations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name_en VARCHAR(120) NOT NULL,name_ar VARCHAR(120),country_code CHAR(2),image_path VARCHAR(255),sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE hotels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,city VARCHAR(100),country VARCHAR(100),star_rating TINYINT UNSIGNED DEFAULT 0,image_path VARCHAR(255),price_per_night DECIMAL(10,2) DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE vehicles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,vehicle_type VARCHAR(80),seats TINYINT UNSIGNED DEFAULT 4,image_path VARCHAR(255),price_per_day DECIMAL(10,2) DEFAULT 0,driver_name VARCHAR(120),sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(140) NOT NULL,email VARCHAR(190),phone VARCHAR(40) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(phone));
CREATE TABLE collaborators (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,collaborator_type ENUM('driver','hotel','transport_company','other') NOT NULL DEFAULT 'other',email VARCHAR(190),phone VARCHAR(40) NOT NULL,company_name VARCHAR(160),notes TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(collaborator_type),INDEX(phone));
CREATE TABLE bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(30) NOT NULL UNIQUE,customer_id INT UNSIGNED,collaborator_id INT UNSIGNED,booking_type ENUM('vehicle','hotel','service','flight','visa','activity') NOT NULL,item_id INT UNSIGNED,source ENUM('admin','mobile') NOT NULL DEFAULT 'admin',start_date DATE,end_date DATE,pickup_location VARCHAR(190),dropoff_location VARCHAR(190),guests SMALLINT UNSIGNED DEFAULT 1,total_amount DECIMAL(12,2) DEFAULT 0,status ENUM('pending','confirmed','in_progress','completed','cancelled') DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_booking_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,CONSTRAINT fk_booking_collaborator FOREIGN KEY(collaborator_id) REFERENCES collaborators(id) ON DELETE SET NULL,INDEX(status),INDEX(source),INDEX(created_at));
